// src/services/websocket.js
import mockBackend from './MockBackend';

class WebSocketService {
  constructor() {
    this.roomId = null;
    this.userId = null;
    this.callbacks = {};
    this.unsubscribe = null;
  }

  connect(roomId, userId, username, callbacks) {
    this.roomId = roomId;
    this.userId = userId;
    this.callbacks = callbacks;

    console.log(`[${new Date().toLocaleTimeString()}] Connecting to room:`, roomId);
    
    // Check if room exists
    let room = mockBackend.getRoom(roomId);
    
    if (!room) {
      // Create room if it doesn't exist (for host)
      console.log('Creating new room as HOST');
      room = mockBackend.createRoom(roomId, userId, username);
      if (callbacks.onRoleAssigned) {
        callbacks.onRoleAssigned({ userId, role: 'HOST' });
      }
    } else {
      // Join existing room
      console.log('Joining existing room as PARTICIPANT');
      const result = mockBackend.joinRoom(roomId, userId, username);
      if (result && callbacks.onRoleAssigned) {
        callbacks.onRoleAssigned({ userId, role: result.role });
        // Send initial state
        if (callbacks.onVideoChange) {
          callbacks.onVideoChange({ videoId: result.state.videoId });
        }
      }
    }
    
    // Subscribe to room events
    this.unsubscribe = mockBackend.subscribe(roomId, (eventType, payload) => {
      console.log(`[${new Date().toLocaleTimeString()}] Received event:`, eventType, payload);
      const callbackName = `on${eventType.charAt(0).toUpperCase() + eventType.slice(1)}`;
      if (this.callbacks[callbackName]) {
        this.callbacks[callbackName](payload);
      }
    });
    
    // Get current participants
    setTimeout(() => {
      const participants = mockBackend.getParticipants(roomId);
      participants.forEach(p => {
        if (p.userId !== userId && this.callbacks.onUserJoined) {
          this.callbacks.onUserJoined(p);
        }
      });
    }, 100);
  }

  sendPlay(roomId, userId) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending PLAY event`);
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'play',
      payload: {},
      senderId: userId
    });
    // Also handle locally
    mockBackend.handleEvent(roomId, 'play', {}, userId);
  }

  sendPause(roomId, userId) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending PAUSE event`);
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'pause',
      payload: {},
      senderId: userId
    });
    mockBackend.handleEvent(roomId, 'pause', {}, userId);
  }

  sendSeek(roomId, userId, time) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending SEEK event to:`, time);
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'seek',
      payload: { time },
      senderId: userId
    });
    mockBackend.handleEvent(roomId, 'seek', { time }, userId);
  }

  sendChangeVideo(roomId, userId, videoId) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending CHANGE_VIDEO event:`, videoId);
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'change_video',
      payload: { videoId },
      senderId: userId
    });
    mockBackend.handleEvent(roomId, 'change_video', { videoId }, userId);
  }

  sendAssignRole(roomId, userId, targetId, role) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending ASSIGN_ROLE event:`, { targetId, role });
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'assign_role',
      payload: { targetId, role },
      senderId: userId
    });
    mockBackend.handleEvent(roomId, 'assign_role', { targetId, role }, userId);
  }

  sendRemoveParticipant(roomId, userId, targetId) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending REMOVE_PARTICIPANT event:`, targetId);
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'remove_participant',
      payload: { targetId },
      senderId: userId
    });
    mockBackend.handleEvent(roomId, 'remove_participant', { targetId }, userId);
  }

  sendChat(roomId, userId, username, message) {
    console.log(`[${new Date().toLocaleTimeString()}] Sending CHAT event:`, message);
    mockBackend.broadcastEvent({
      roomId,
      eventType: 'chat',
      payload: { username, message },
      senderId: userId
    });
    mockBackend.handleEvent(roomId, 'chat', { username, message }, userId);
  }

  disconnect() {
    if (this.unsubscribe) {
      this.unsubscribe();
    }
    if (this.roomId && this.userId) {
      mockBackend.broadcastEvent({
        roomId: this.roomId,
        eventType: 'leave_room',
        payload: {},
        senderId: this.userId
      });
      mockBackend.handleEvent(this.roomId, 'leave_room', {}, this.userId);
    }
  }
}

export default WebSocketService;
